import { TrendingDownIcon, TrendingUpIcon } from "lucide-react";

import { NumberFlow } from "@/components/dx/number-flow";
import { Badge } from "@/components/ui/badge";
import { Card, CardAction, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";

type Kpi = { label: string; value: number; prefix?: string; suffix?: string; delta: number; note: string; format?: Intl.NumberFormatOptions };

const int = { maximumFractionDigits: 0 };
const one = { maximumFractionDigits: 1 };

export function SectionCards({ scale }: { scale: number }) {
  const kpis: Kpi[] = [
    { label: "Total revenue", value: 1250 * scale, prefix: "$", delta: 12.5, note: "Trending up this period", format: int },
    { label: "New customers", value: 1234 * scale * 0.08, delta: -20, note: "Acquisition needs attention", format: int },
    { label: "Active accounts", value: 45678 * Math.min(scale, 3) * 0.33, delta: 12.5, note: "Strong user retention", format: int },
    { label: "Growth rate", value: 4.5 + scale * 0.2, suffix: "%", delta: 4.5, note: "Meets growth projections", format: one },
  ];
  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {kpis.map((k) => {
        const up = k.delta >= 0;
        return (
          <Card key={k.label} variant="tonal" className="gap-3">
            <CardHeader>
              <CardDescription>{k.label}</CardDescription>
              <CardTitle className="text-3xl font-normal tracking-[-0.02em]">
                <NumberFlow value={k.value} prefix={k.prefix} suffix={k.suffix} format={k.format} />
              </CardTitle>
              <CardAction>
                <Badge variant={up ? "success" : "destructive"}>
                  {up ? <TrendingUpIcon /> : <TrendingDownIcon />}
                  {up ? "+" : ""}
                  {k.delta}%
                </Badge>
              </CardAction>
            </CardHeader>
            <CardFooter className="text-[13px] text-muted-foreground">{k.note}</CardFooter>
          </Card>
        );
      })}
    </div>
  );
}

import type { ColumnDef } from "@tanstack/react-table";
import { MoreHorizontalIcon } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { DataTable, DataTableColumnHeader } from "@/components/ui/data-table";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Meter } from "@/components/ui/meter";

type Project = { name: string; owner: string; status: "On track" | "At risk" | "Done"; progress: number; due: string };

const projects: Project[] = [
  { name: "Registry v1", owner: "Ada L.", status: "On track", progress: 72, due: "Oct 14" },
  { name: "CLI init flow", owner: "Grace H.", status: "At risk", progress: 38, due: "Oct 09" },
  { name: "Docs search", owner: "Alan T.", status: "Done", progress: 100, due: "Sep 28" },
  { name: "Blocks gallery", owner: "Katherine J.", status: "On track", progress: 64, due: "Oct 21" },
  { name: "Theme builder", owner: "Linus T.", status: "At risk", progress: 22, due: "Nov 02" },
  { name: "Figma kit", owner: "Margaret H.", status: "On track", progress: 51, due: "Oct 30" },
  { name: "A11y audit", owner: "Tim B.", status: "Done", progress: 100, due: "Sep 19" },
  { name: "Motion tokens", owner: "Hedy L.", status: "On track", progress: 80, due: "Oct 11" },
  { name: "RTL support", owner: "Dennis R.", status: "At risk", progress: 15, due: "Nov 18" },
];

const tone = { "On track": "info", "At risk": "warning", Done: "success" } as const;

const columns: ColumnDef<Project>[] = [
  { accessorKey: "name", header: ({ column }) => <DataTableColumnHeader column={column} title="Project" />, cell: ({ row }) => <span className="font-medium">{row.getValue("name")}</span> },
  { accessorKey: "owner", header: "Owner" },
  { accessorKey: "status", header: "Status", cell: ({ row }) => <Badge variant={tone[row.original.status]}>{row.original.status}</Badge> },
  {
    accessorKey: "progress",
    header: ({ column }) => <DataTableColumnHeader column={column} title="Progress" />,
    cell: ({ row }) => (
      <div className="flex min-w-32 items-center gap-3">
        <Meter value={row.original.progress} className="flex-1" aria-label={`${row.original.name} progress`} />
        <span className="w-9 text-right text-xs text-muted-foreground tabular-nums">{row.original.progress}%</span>
      </div>
    ),
  },
  { accessorKey: "due", header: "Due" },
  {
    id: "actions",
    cell: () => (
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon-sm" aria-label="Open menu" />}>
          <MoreHorizontalIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem>Edit</DropdownMenuItem>
          <DropdownMenuItem>Duplicate</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive">Archive</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
  },
];

export function ProjectsTable() {
  return <DataTable columns={columns} data={projects} filterColumn="name" filterPlaceholder="Filter projects…" pageSize={6} />;
}

import * as React from "react";
import { DownloadIcon } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { toast } from "@/components/ui/sonner";
import { AppSidebar } from "./app-sidebar";
import { ChartArea, type Range } from "./chart-area";
import { ProjectsTable } from "./projects-table";
import { SectionCards } from "./section-cards";

const scaleFor: Record<Range, number> = { "7d": 1, "30d": 4.2, "90d": 12.8 };

export default function Dashboard01() {
  const [range, setRange] = React.useState<Range>("30d");
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset>
        <header className="flex h-14 shrink-0 items-center gap-2 border-b border-outline-variant px-4">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mx-1 h-4" />
          <h1 className="text-sm font-medium">Dashboard</h1>
          <Button size="sm" variant="tonal" className="ml-auto" onClick={() => toast.success("Report exported")}>
            <DownloadIcon /> Export
          </Button>
        </header>
        <div className="flex flex-1 flex-col gap-4 p-4 md:gap-6 md:p-6">
          <SectionCards scale={scaleFor[range]} />
          <ChartArea range={range} onRangeChange={setRange} />
          <ProjectsTable />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

import * as React from "react";
import { Area, AreaChart, CartesianGrid, XAxis } from "recharts";

import { Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "@/components/ui/chart";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";

const config = {
  desktop: { label: "Desktop", color: "var(--chart-1)" },
  mobile: { label: "Mobile", color: "var(--chart-5)" },
} satisfies ChartConfig;

// Deterministic pseudo-random series so the chart is stable across renders.
const series = Array.from({ length: 90 }, (_, i) => {
  const d = new Date(2026, 6, 1);
  d.setDate(d.getDate() + i);
  const wave = Math.sin(i / 6) * 80 + Math.cos(i / 13) * 60;
  return {
    date: d.toISOString().slice(0, 10),
    desktop: Math.round(260 + wave + ((i * 37) % 90)),
    mobile: Math.round(170 + wave * 0.7 + ((i * 53) % 70)),
  };
});

export const ranges = { "90d": 90, "30d": 30, "7d": 7 } as const;
export type Range = keyof typeof ranges;

export function ChartArea({ range, onRangeChange }: { range: Range; onRangeChange: (r: Range) => void }) {
  const data = React.useMemo(() => series.slice(-ranges[range]), [range]);
  return (
    <Card>
      <CardHeader>
        <CardTitle>Total visitors</CardTitle>
        <CardDescription>Desktop and mobile, last {ranges[range]} days</CardDescription>
        <CardAction>
          <ToggleGroup size="sm" value={[range]} onValueChange={(v) => v[0] && onRangeChange(v[0] as Range)}>
            {(Object.keys(ranges) as Range[]).map((r) => (
              <ToggleGroupItem key={r} value={r} className="px-3">
                {r}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </CardAction>
      </CardHeader>
      <CardContent>
        <ChartContainer config={config} className="aspect-auto h-64 w-full">
          <AreaChart data={data} margin={{ left: 4, right: 4 }}>
            <defs>
              {Object.keys(config).map((k) => (
                <linearGradient key={k} id={`dash-fill-${k}`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={`var(--color-${k})`} stopOpacity={0.3} />
                  <stop offset="100%" stopColor={`var(--color-${k})`} stopOpacity={0.02} />
                </linearGradient>
              ))}
            </defs>
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="date"
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              minTickGap={32}
              tickFormatter={(v: string) => new Date(v).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
            />
            <ChartTooltip
              cursor={false}
              content={
                <ChartTooltipContent
                  indicator="dot"
                  labelFormatter={(v) => new Date(String(v)).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                />
              }
            />
            <Area dataKey="mobile" type="natural" stroke="var(--color-mobile)" strokeWidth={2} fill="url(#dash-fill-mobile)" stackId="a" />
            <Area dataKey="desktop" type="natural" stroke="var(--color-desktop)" strokeWidth={2} fill="url(#dash-fill-desktop)" stackId="a" />
          </AreaChart>
        </ChartContainer>
      </CardContent>
    </Card>
  );
}
